export type Listing={id:number;slug:string;name:string;category:string;style:string;price:number;creator:string;Icon:LucideIcon;color:string;aliases:string[];description:string};
export const slugify=(value:string)=>value.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
const icon=(id:number,name:string,category:string,style:string,price:number,creator:string,Icon:LucideIcon,color:string,aliases:string[]):Listing=>({
  id,slug:slugify(name),name,category,style,price,creator,Icon,color,aliases,
  description:`A polished ${name.toLowerCase()} icon created for modern ${category.toLowerCase()} interfaces, products and brand systems.`,
});

